    private static GRepData? Decode(string base64, uint owner)
    {
        byte[] data = Convert.FromBase64String(base64);
        return GRepParserV2.ParseExactPlanarSpaceBoundary(data, 0, (uint)(data.Length - 16), owner);
    }

    private static void AssertClosedShell(GRepData body, int faces)
    {
        Assert.Equal(faces, body.Faces.Count);
        var solid = Assert.Single(body.Solids);
        Assert.True(solid.IsClosed);
        var geometry = ElementBuilder.BuildGeometryData(body)!;
        Assert.True(IfcExporter.TryOrientExactFacetedShell(geometry.Faces, geometry.BrepSolids![0].FaceIndices, out _,
            triangulateNonPlanarFaces: false));
    }

    [Fact]
    public void CacheThatClosesWithinTheLattice_IsReadAsBefore() =>
        AssertClosedShell(Decode(Room2765099, 2765099)!, 7);

    [Fact]
    public void LoopsThatMissEachOtherByAFewMicrometres_AreWeldedAtTheVertexTolerance() =>
        AssertClosedShell(Decode(Room6957647, 6957647)!, 19);

    [Fact]
    public void CornerSplitIntoTwoVerticesHalfAMillimetreApart_IsOneVertexOfTheShell()
    {
        var body = Decode(Room2776053, 2776053)!;
        AssertClosedShell(body, 8);
        // The two hexagons share all six corners with the four-corner sides: 6 + 6 + 6 * 4 vertex uses over 12 vertices.
        var corners = body.Faces.SelectMany(face => face.Vertices!)
            .Select(point => (Math.Round(point[0] * 1000), Math.Round(point[1] * 1000), Math.Round(point[2] * 1000)))
            .Distinct().ToList();
        Assert.Equal(12, corners.Count);
    }

    [Fact]
    public void CurvedCache_StaysUnread() => Assert.Null(Decode(Room2795696, 2795696));

    [Fact]
    public void OwnerThatIsNotTheBlocksElement_StaysUnread() => Assert.Null(Decode(Room2776053, 2776054));
}
